// Eingabe der Runtime: { title, start, end, location?, description?, calendar?, attendees? }
const incoming = $input.first().json;
const inp = incoming.body && typeof incoming.body === 'object' ? incoming.body : incoming;
for (const field of ['title', 'start', 'end']) {
  if (typeof inp[field] !== 'string' || inp[field].trim() === '') {
    throw new Error('cal-create: Feld "' + field + '" fehlt');
  }
}
const attendees = typeof inp.attendees === 'string' && inp.attendees
  ? inp.attendees.split(',').map((a) => a.trim()).filter(Boolean)
  : [];
return [{ json: {
  calendar: typeof inp.calendar === 'string' && inp.calendar ? inp.calendar : 'primary',
  summary: inp.title,
  start: inp.start,
  end: inp.end,
  location: inp.location || '',
  description: inp.description || '',
  attendees
} }];

const e = $input.first().json || {};
return [{ json: {
  event_id: String(e.id || ''),
  html_link: e.htmlLink || '',
  calendar: (e.organizer && e.organizer.email) || 'primary',
  created: !!e.id
} }];
